    /**
     * Tests getting all BOMItems.
     *
     * @return    Collection
     */
    public List<BOMItem> testGetAll() throws Throwable {
    LOGGER.info( "BOMItemTest:testGetAll() - Retrieving Collection of BOMItems:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all BOMItem : " );
    List<BOMItem> collection  = null;

    try {
        // call the static get method on the BOMItemService
        collection = service.getAllBOMItem();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            BOMItem currEntity  = null;
            Iterator<BOMItem> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getBOMItemId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

